<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount,nextTick,watch} from 'vue';
import CommunicationManagement from './CommunicationManagement.vue';
import EmojiPicker from './EmojiPicker.vue';
import ChatDetails from './ChatDetails.vue';
import {parseChatDate,conversationTime} from './chatTime';
import MessageActions from './MessageActions.vue';
import CommunicationProfile from './CommunicationProfile.vue';
import StatusPanel from './StatusPanel.vue';
const pinned=ref<{id:number;body:string|null;sender_name:string;attachment_name:string|null}[]>([]),forwardMessage=ref<Message|null>(null),forwardTarget=ref(''),forwardFilter=ref(''),notice=ref('');
const detailMode=ref(''),highlight=ref<number|null>(null);
async function jumpToMessage(id:number){if(!active.value)return;const chat=active.value,version=generation;try{const result=await api('/conversations/'+chat+'/messages','GET',undefined,{around:String(id)});if(chat!==active.value||version!==generation)return;messages.value=result.messages;more.value=result.messages.length>=25;highlight.value=id;await nextTick();document.getElementById('chat-message-'+id)?.scrollIntoView({block:'center',behavior:'smooth'});}catch(e){error.value=(e as Error).message;}}
function shortTime(value:string){return new Date(value.replace(' ','T')+'Z').toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});}
function dayLabel(value:string){return new Date(value.replace(' ','T')+'Z').toLocaleDateString([],{weekday:'short',month:'short',day:'numeric'});}
const composerInput=ref<HTMLTextAreaElement|null>(null);
let polling=false;
async function insertEmoji(emoji:string){const input=composerInput.value;const start=input?.selectionStart??draft.value.length,end=input?.selectionEnd??start;if(draft.value.length-(end-start)+emoji.length>10000)return;draft.value=draft.value.slice(0,start)+emoji+draft.value.slice(end);await nextTick();input?.focus();input?.setSelectionRange(start+emoji.length,start+emoji.length);}
const props=defineProps<{csrf?:string}>();
const emit=defineEmits<{profileUpdated:[name:string,csrf:string]}>();
type Person={id:number;name:string;email:string;company_id?:number;avatar_url?:string|null};
type Conversation={id:number;kind:string;name:string;company_name?:string;company_id?:number;members:Person[];preview:string;last_message_at:string|null;unread:number};
type Message={id:number;sender_id:number|null;sender_name:string;body:string|null;reply_to:number|null;attachment_name:string|null;attachment_url:string|null;created_at:string;edited_at:string|null;deleted_at:string|null;forwarded?:boolean;pinned_at?:string|null;reactions:{user_id:number;name:string;emoji:string}[]};
type Company={id:number;name:string};
type Story={author_name?:string;author_avatar?:string|null;author_id?:number|null;id:number;title:string;body:string;expires_at:string;created_at:string;attachment_url?:string|null;attachment_name?:string|null;attachment_mime?:string|null};
type Snapshot={profile:{id:number;name:string;email:string;avatar_url:string|null}|null;admin:boolean;manager:boolean;company_id:number|null;user_id:number|null;people:Person[];review_people:Person[];companies:Company[];conversations:Conversation[];stories:Story[];viewed_user:Person|null};
const data=ref<Snapshot|null>(null), messages=ref<Message[]>([]), active=ref<number|null>(null), draft=ref(''), filter=ref(''), search=ref(''), error=ref(''), sending=ref(false), refreshing=ref(false), viewUser=ref(''), reviewing=ref(false), file=ref<File|null>(null), fileInput=ref<HTMLInputElement|null>(null), reply=ref<Message|null>(null), list=ref<HTMLElement|null>(null), more=ref(false);
const modal=ref(''), modalName=ref(''), modalBody=ref(''), modalKind=ref('direct'), modalTeam=ref(''), selected=ref<number[]>([]), saving=ref(false), story=ref<Story|null>(null), auditRows=ref<any[]>([]);
const storyFile=ref<File|null>(null),storyInput=ref<HTMLInputElement|null>(null);
function clearStoryAttachment(){storyFile.value=null;if(storyInput.value)storyInput.value.value='';}
const workspaceInfo=ref(false);
const section=ref('Chats'), announcementCompanies=ref<number[]>([]), announcementFile=ref<File|null>(null);
const storyClock=ref(Date.now());
let timer:ReturnType<typeof setInterval>|undefined, generation=0, ticks=0;
const monitoring=computed(()=>!!viewUser.value);
const current=computed(()=>data.value?.conversations.find(c=>c.id===active.value&&(section.value==='Communities'?c.kind==='community':c.kind!=='community')));
const conversations=computed(()=>data.value?.conversations.filter(c=>(section.value==='Communities'?c.kind==='community':c.kind!=='community')&&(c.name+' '+(c.company_name||'')).toLowerCase().includes(filter.value.toLowerCase()))||[]);
const candidates=computed(()=>data.value?.people.filter(p=>(data.value?.admin||p.id!==data.value?.user_id)&&(modalKind.value!=='group'||!modalTeam.value||p.company_id===Number(modalTeam.value)))||[]);
const alerts=computed(()=>data.value?.conversations.filter(c=>c.kind==='community'&&c.unread>0)||[]);
function url(path:string,extra:Record<string,string>={}){const query=new URLSearchParams(extra);if(viewUser.value)query.set('view_user',viewUser.value);return '/communication/api'+path+(query.size?'?'+query:'');}
async function api(path:string,method='GET',body?:any,extra:Record<string,string>={}){
 const form=body instanceof FormData;
 const response=await fetch(url(path,extra),{method,headers:{Accept:'application/json','X-CSRF-TOKEN':props.csrf||'',...(!form?{'Content-Type':'application/json'}:{})},body:body?(form?body:JSON.stringify(body)):undefined});
 if(!response.ok){const issue=await response.json().catch(()=>({}));throw new Error(Object.values(issue.errors||{}).flat().join(' ')||issue.message||'Unable to complete this action.');}
 return response.json();
}
let storiesPolling=false,lastStorySync=0;
async function syncStories(){
 if(storiesPolling||!data.value||document.hidden||reviewing.value)return;
 storiesPolling=true;lastStorySync=Date.now();const review=viewUser.value;
 try{const result=await api('/stories');if(review!==viewUser.value||!data.value)return;data.value.stories=result.stories;if(story.value&&!result.stories.some((s:Story)=>s.id===story.value?.id))story.value=null;}
 catch{/* Retry on the next tick after a temporary connection failure. */}
 finally{storiesPolling=false;}
}
function resumeStories(){if(!document.hidden)void syncStories();}
async function refresh(){
 if(refreshing.value||reviewing.value)return;
 refreshing.value=true;const version=generation;
 try{const result=await api('');if(version===generation){data.value=result;if(story.value&&!result.stories.some((s:Story)=>s.id===story.value?.id))story.value=null;}if(version===generation&&active.value&&!result.conversations.some((c:Conversation)=>c.id===active.value)){active.value=null;messages.value=[];}
 if(active.value&&version===generation)await loadMessages(false);
 }catch(e){error.value=(e as Error).message;}finally{refreshing.value=false;}
}
async function loadMessages(audit=false,older=false){
 if(!active.value)return;
 const id=active.value,version=generation;const extra:Record<string,string>={};if(audit)extra.audit='1';if(older&&messages.value.length)extra.before=String(messages.value[0].id);
 const result=await api('/conversations/'+id+'/messages','GET',undefined,extra);
 if(id!==active.value||version!==generation)return;
 pinned.value=result.pinned||[];
 const nearBottom=!list.value||list.value.scrollHeight-list.value.scrollTop-list.value.clientHeight<100;
 const merged=new Map(messages.value.map(m=>[m.id,m]));for(const m of result.messages)merged.set(m.id,m);messages.value=[...merged.values()].sort((a,b)=>a.id-b.id);
 if(older||messages.value.length<=50)more.value=result.has_more;
 if(!data.value?.admin&&current.value)current.value.unread=0;
 if(audit||(!older&&nearBottom&&!highlight.value)){await nextTick();list.value?.scrollTo({top:list.value.scrollHeight});}
}
async function open(c:Conversation){if(c.kind==='community')section.value='Communities';else section.value='Chats';generation++;detailMode.value='';highlight.value=null;active.value=c.id;pinned.value=[];messages.value=[];reply.value=null;search.value='';draft.value='';file.value=null;error.value='';try{await loadMessages(true);}catch(e){error.value=(e as Error).message;}}
async function changeReview(){
 reviewing.value=true;generation++;active.value=null;messages.value=[];error.value='';
 try{data.value=await api(viewUser.value?'/review':'',viewUser.value?'POST':'GET',viewUser.value?{view_user:Number(viewUser.value)}:undefined);}catch(e){error.value=(e as Error).message;}finally{reviewing.value=false;}
}
async function send(){
 if(!active.value||sending.value||monitoring.value||(!draft.value.trim()&&!file.value))return;
 const id=active.value,version=generation,body=draft.value,attachment=file.value,replyTo=reply.value;
 highlight.value=null;sending.value=true;error.value='';
 try{
 const form=new FormData();form.append('body',body);if(replyTo)form.append('reply_to',String(replyTo.id));if(attachment)form.append('attachment',attachment);
 const result=await api('/conversations/'+id+'/messages','POST',form);
 const conversation=data.value?.conversations.find(c=>c.id===id);if(conversation){conversation.preview=body||attachment?.name||'Attachment';conversation.last_message_at=result.message.created_at;if(data.value)data.value.conversations=[conversation,...data.value.conversations.filter(c=>c.id!==id)];}
 if(active.value===id&&version===generation){
 if(draft.value===body)draft.value='';if(reply.value===replyTo)reply.value=null;if(file.value===attachment){file.value=null;if(fileInput.value)fileInput.value.value='';}
 const merged=new Map(messages.value.map(m=>[m.id,m]));merged.set(result.message.id,result.message);messages.value=[...merged.values()].sort((a,b)=>a.id-b.id);
 await nextTick();list.value?.scrollTo({top:list.value.scrollHeight});
 }
 }catch(e){error.value=(e as Error).message;}finally{sending.value=false;}
}

const forwardChoices=computed(()=>data.value?.conversations.filter(c=>(data.value?.admin||c.kind!=='community')&&c.name.toLowerCase().includes(forwardFilter.value.toLowerCase()))||[]);
function avatar(id:number|null|undefined){const photo=data.value?.people.find(p=>p.id===id)?.avatar_url;return photo?photo+(viewUser.value?'&view_user='+viewUser.value:''):null;}
function conversationAvatar(c:Conversation){return c.kind==='direct'?avatar(c.members.find(p=>p.id!==(monitoring.value?Number(viewUser.value):data.value?.user_id))?.id):null;}
function senderName(m:Message){return data.value?.people.find(p=>p.id===m.sender_id)?.name||m.sender_name;}
function contactName(m:Message){return current.value?.kind==='group'&&!data.value?.admin&&m.sender_id!==data.value?.user_id?data.value?.people.find(p=>p.id===m.sender_id)?.name:undefined;}
async function messagePerson(m:Message){if(!m.sender_id)return;try{const result=await api('/conversations','POST',{kind:'direct',member_ids:[m.sender_id]});generation++;data.value=await api('');const c=data.value?.conversations.find(c=>c.id===result.id);if(c)await open(c);}catch(e){error.value=(e as Error).message;}}
async function copyMessage(m:Message){try{await navigator.clipboard.writeText(m.body||m.attachment_name||'');notice.value='Message copied.';}catch{error.value='Clipboard access is unavailable. Select the message text to copy it.';}}
async function action(m:Message,kind:string){if(kind==='reply'){reply.value=m;composerInput.value?.focus();}else if(kind==='edit')await editMessage(m);else if(kind==='delete')await deleteMessage(m);else if(kind==='copy')await copyMessage(m);else if(kind==='download'&&m.attachment_url){const link=document.createElement('a');link.href=download(m);link.download=m.attachment_name||'attachment';document.body.appendChild(link);link.click();link.remove();}else if(kind==='contact')await messagePerson(m);else if(kind==='forward'){forwardMessage.value=m;forwardTarget.value='';forwardFilter.value='';modal.value='forward';}else if(kind==='pin'){try{await api('/messages/'+m.id+'/pin','POST',{pinned:!m.pinned_at});await loadMessages();}catch(e){error.value=(e as Error).message;}}}
async function forward(){if(!forwardMessage.value||!forwardTarget.value)return;saving.value=true;try{await api('/messages/'+forwardMessage.value.id+'/forward','POST',{conversation_id:Number(forwardTarget.value)});modal.value='';forwardMessage.value=null;notice.value='Message forwarded.';await refresh();}catch(e){error.value=(e as Error).message;}finally{saving.value=false;}}
async function profileUpdated(profile:{name:string},token:string){emit('profileUpdated',profile.name,token);generation++;data.value=await api('');}

type StoryViewer={id:number;name:string;email:string;avatar_url:string|null;first_viewed_at:string;last_viewed_at:string};
const storyViewers=ref<StoryViewer[]>([]),viewerTotal=ref(0),viewerNext=ref<number|null>(null),viewersOpen=ref(false),viewerBusy=ref(false),viewerError=ref('');
const reactionSelection=ref<Message|null>(null),reactionFilter=ref('All');
const reactionMessage=computed(()=>messages.value.find(m=>m.id===reactionSelection.value?.id)||reactionSelection.value);
const reactionTabs=computed(()=>['All',...new Set(reactionMessage.value?.reactions.map(r=>r.emoji)||[])]);
const reactionPeople=computed(()=>reactionMessage.value?.reactions.filter(r=>reactionFilter.value==='All'||r.emoji===reactionFilter.value)||[]);
let viewerRequest=0;
async function loadStoryViewers(older=false){if(!story.value)return;const id=story.value.id,token=++viewerRequest;viewerBusy.value=true;viewerError.value='';try{const result=await api('/stories/'+id+'/viewers','GET',undefined,{page:String(older?viewerNext.value||1:1)});if(story.value?.id!==id||token!==viewerRequest)return;storyViewers.value=older?[...storyViewers.value,...result.viewers]:result.viewers;viewerTotal.value=result.total;viewerNext.value=result.next_page;}catch(e){if(story.value?.id===id&&token===viewerRequest)viewerError.value=(e as Error).message;}finally{if(token===viewerRequest)viewerBusy.value=false;}}
function storyPosted(s:Story){const date=parseChatDate(s.created_at),now=new Date(storyClock.value);const day=(d:Date)=>Date.UTC(d.getFullYear(),d.getMonth(),d.getDate());const days=Math.round((day(now)-day(date))/86400000);return (days===0?'Today':days===1?'Yesterday':date.toLocaleDateString())+' at '+date.toLocaleTimeString('en',{hour:'numeric',minute:'2-digit'});}
const storyPlayback=ref(0),storyPaused=ref(false),storyHeld=ref(false),storyReady=ref(false),storyMedia=ref<HTMLMediaElement|null>(null);
let playbackTimer:ReturnType<typeof setInterval>|undefined;
function advanceStatus(){if(!story.value)return;const index=visibleStories.value.findIndex(s=>s.id===story.value?.id),next=visibleStories.value[index+1];if(next)void openStory(next);else story.value=null;}
function releaseStatus(){storyHeld.value=false;}
function toggleStatusPlayback(){storyPaused.value=!storyPaused.value;if(storyMedia.value){if(storyPaused.value)storyMedia.value.pause();else void storyMedia.value.play().catch(()=>{storyPaused.value=true;});}}
function mediaStatusProgress(event:Event){const media=event.target as HTMLMediaElement;if(Number.isFinite(media.duration)&&media.duration>0)storyPlayback.value=Math.min(100,media.currentTime/media.duration*100);}
watch(()=>story.value?.id,()=>{
 if(playbackTimer)clearInterval(playbackTimer);storyPlayback.value=0;storyPaused.value=false;storyHeld.value=false;storyMedia.value=null;if(!story.value)return;
 storyReady.value=!story.value.attachment_mime?.startsWith('image/');const duration=story.value.attachment_mime?.startsWith('image/')?7000:Math.min(15000,Math.max(5000,(story.value.body?.length||0)*60));let last=performance.now();
 playbackTimer=setInterval(()=>{const now=performance.now(),delta=now-last;last=now;if(!story.value||document.hidden||storyPaused.value||storyHeld.value||viewersOpen.value||deletingStory.value!==null||!storyReady.value)return;if(story.value.attachment_mime?.match(/^(video|audio)\//))return;storyPlayback.value=Math.min(100,storyPlayback.value+delta/duration*100);if(storyPlayback.value>=100)advanceStatus();},100);
});
function nextStory(direction:number){if(!story.value)return;const index=visibleStories.value.findIndex(s=>s.id===story.value?.id),next=visibleStories.value[index+direction];if(next)void openStory(next);}
function storyAge(s:Story){const seconds=Math.max(0,Math.floor((storyClock.value-parseChatDate(s.created_at).getTime())/1000));if(seconds<60)return 'Just now';const minutes=Math.floor(seconds/60);if(minutes<60)return minutes+' minute'+(minutes===1?'':'s')+' ago';const hours=Math.floor(minutes/60);return hours+' hour'+(hours===1?'':'s')+' ago';}
function storyRemaining(s:Story){const seconds=Math.max(0,Math.ceil((parseChatDate(s.expires_at).getTime()-storyClock.value)/1000));if(!seconds)return 'Expired';const hours=Math.floor(seconds/3600),minutes=Math.floor(seconds%3600/60);return 'Hides in '+(hours?hours+'h ':'')+(hours||minutes?minutes+'m':seconds+'s');}
const visibleStories=computed(()=>data.value?.stories.filter(s=>parseChatDate(s.expires_at).getTime()>storyClock.value)||[]);
function canViewStoryViewers(s:Story){return !monitoring.value && (!!data.value?.admin || (!!data.value?.manager && s.author_id===data.value?.user_id));}
async function openStory(s:Story){story.value=s;storyViewers.value=[];viewerTotal.value=0;viewerNext.value=null;viewersOpen.value=false;viewerError.value='';if(canViewStoryViewers(s)){await loadStoryViewers();}else if(data.value?.admin){}else{try{await api('/stories/'+s.id+'/view','POST');}catch(e){viewerError.value=(e as Error).message;}}}
function showReactions(m:Message){reactionSelection.value=m;reactionFilter.value='All';modal.value='reactions';}

function newModal(kind:string){modal.value=kind;modalName.value='';modalBody.value='';modalKind.value=data.value?.admin?'group':'direct';modalTeam.value=String(data.value?.company_id||data.value?.companies[0]?.id||'');selected.value=[];announcementCompanies.value=[];announcementFile.value=null;storyFile.value=null;error.value='';}
async function save(){if(saving.value)return;
 saving.value=true;error.value='';
 try{
 if(modal.value==='announcement'){const form=new FormData();form.append('body',modalBody.value);for(const id of announcementCompanies.value)form.append('company_ids[]',String(id));if(announcementFile.value)form.append('attachment',announcementFile.value);await api('/announcements','POST',form);}
 else if(modal.value==='story'){const form=new FormData();form.append('body',modalBody.value);if(storyFile.value)form.append('attachment',storyFile.value);await api('/stories','POST',form);}
 else{const result=await api('/conversations','POST',{kind:modalKind.value,name:modalName.value,company_id:modalTeam.value?Number(modalTeam.value):null,member_ids:selected.value});generation++;data.value=await api('');const c=data.value?.conversations.find(c=>c.id===result.id);if(c)await open(c);}
 modal.value='';await refresh();
 }catch(e){error.value=(e as Error).message;}finally{saving.value=false;}
}
async function editMessage(m:Message){const body=window.prompt('Edit message',m.body||'');if(body===null||!body.trim())return;try{await api('/messages/'+m.id,'PATCH',{body});await loadMessages();}catch(e){error.value=(e as Error).message;}}
async function deleteMessage(m:Message){if(!confirm('Delete this message for everyone?'))return;try{await api('/messages/'+m.id,'DELETE');await loadMessages();}catch(e){error.value=(e as Error).message;}}
const deletingStory=ref<number|null>(null);
async function removeStory(s:Story){if(deletingStory.value!==null||!data.value?.admin||monitoring.value||!confirm('Delete this status for everyone?'))return;deletingStory.value=s.id;try{await api('/stories/'+s.id,'DELETE');if(data.value)data.value.stories=data.value.stories.filter(x=>x.id!==s.id);if(story.value?.id===s.id)story.value=null;await refresh();}catch(e){error.value=(e as Error).message;}finally{deletingStory.value=null;}}
async function showAudits(){try{auditRows.value=await api('/audits');modal.value='audit';}catch(e){error.value=(e as Error).message;}}
async function react(m:Message,emoji:string){try{await api('/messages/'+m.id+'/reactions','POST',{emoji});await loadMessages();}catch(e){error.value=(e as Error).message;}}
function reactionGroups(m:Message){return [...new Set(m.reactions.map(r=>r.emoji))].map(emoji=>({emoji,names:m.reactions.filter(r=>r.emoji===emoji).map(r=>r.name),mine:m.reactions.some(r=>r.emoji===emoji&&r.user_id===data.value?.user_id)}));}
function mine(m:Message){return data.value?.admin?m.sender_id===null&&m.sender_name==='Super Admin':m.sender_id===data.value?.user_id;}
function timestamp(value:string){return new Date(value.replace(' ','T')+'Z').toLocaleString([], {month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});}
function attached(event:Event){file.value=(event.target as HTMLInputElement).files?.[0]||null;}
function storyAttachment(s:Story,download=false){const query=new URLSearchParams();if(viewUser.value)query.set('view_user',viewUser.value);if(download)query.set('download','1');return s.attachment_url+(query.size?'?'+query.toString():'');}
function download(m:Message){return m.attachment_url+(viewUser.value?'?view_user='+viewUser.value:'');}
onMounted(async()=>{document.addEventListener('pointerup',releaseStatus);document.addEventListener('pointercancel',releaseStatus);document.addEventListener('visibilitychange',resumeStories);window.addEventListener('focus',resumeStories);await refresh();timer=setInterval(()=>{storyClock.value=Date.now();if(storyClock.value-lastStorySync>=2000)void syncStories();if(story.value&&parseChatDate(story.value.expires_at).getTime()<=storyClock.value)story.value=null;if(document.hidden||reviewing.value||refreshing.value||sending.value||polling)return;ticks++;polling=true;const task=ticks%15===0||(!active.value&&ticks%3===0)?refresh():active.value?loadMessages():Promise.resolve();void task.catch(e=>{error.value=(e as Error).message;}).finally(()=>{polling=false;});},1000);});
onBeforeUnmount(()=>{if(playbackTimer)clearInterval(playbackTimer);document.removeEventListener('pointerup',releaseStatus);document.removeEventListener('pointercancel',releaseStatus);document.removeEventListener('visibilitychange',resumeStories);window.removeEventListener('focus',resumeStories);if(timer)clearInterval(timer);generation++;});
</script>

<template>
<div class="comm-workspace" :class="{'has-chat':!!current&&section!=='Status'}">
 <nav class="comm-app-rail" aria-label="Communication sections">
 <a href="/products" class="comm-rail-home" aria-label="Back to products" title="Back to products">J</a>
 <button v-for="item in [{name:'Chats',path:'M4 4h16v12H9l-5 4V4m4 4h8m-8 4h6'},{name:'Status',path:'M9 3a9 9 0 0 0-6 8m1 6a9 9 0 0 0 14 2m3-6A9 9 0 0 0 15 3M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0'},{name:'Communities',path:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-4m-6-8a4 4 0 1 1-8 0 4 4 0 0 1 8 0m3-4a4 4 0 0 1 0 8'}]" :key="item.name" @click="section=item.name;detailMode=''" :class="{active:section===item.name}" :aria-label="item.name" :title="item.name" :aria-pressed="section===item.name"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path :d="item.path"/></svg></button>
 <div class="comm-rail-bottom"><button v-if="data?.manager&&!monitoring" aria-label="Communities and invitations" title="Communities and invitations" @click="newModal('management')"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><rect x="4" y="6" width="16" height="14" rx="2"/><path d="M8 6V4h8v2m-4 5v6m-3-3h6"/></svg></button><button aria-label="Workspace settings and information" title="Workspace settings and information" @click="workspaceInfo=!workspaceInfo" :aria-expanded="workspaceInfo"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><circle cx="12" cy="12" r="8"/><path d="M12 11v6m0-10v1"/></svg></button><button v-if="data?.profile&&!monitoring" class="comm-rail-profile" aria-label="Edit your profile" title="Your profile" @click="modal='profile'"><img v-if="data.profile.avatar_url" :src="data.profile.avatar_url" alt=""><span v-else>{{data.profile.name.slice(0,1)}}</span></button></div>
 </nav>
 <div class="comm-workspace-controls" v-if="workspaceInfo">
 <div class="comm-title"><div><span class="comm-brand-icon">C</span><div><h1>Communication</h1><p>Your chats. Your communities.</p></div></div><a href="/admin" v-if="data?.admin">Administration &rarr;</a><a href="/products" v-else>All products &rarr;</a></div>
 <div class="comm-disclosure"><span>&#128274;</span> Company workspace &middot; Conversations and files are accessible to the Super Admin. Administrator reviews are logged.</div>
 <div v-if="data?.admin" class="comm-admin-bar"><label>Review employee <select v-model="viewUser" @change="changeReview"><option value="">All company conversations</option><option v-for="p in data.review_people" :key="p.id" :value="p.id">{{p.name}} &middot; {{p.email}}</option></select></label><button @click="showAudits">Review log</button><button :disabled="monitoring" @click="newModal('announcement')">Send announcement</button><button :disabled="monitoring" @click="newModal('story')">Publish story</button></div>
 <div class="comm-onboarding-bar" v-if="data?.manager&&!monitoring"><button @click="newModal('management')">Communities &amp; invitations</button></div>
 </div>
 <div class="comm-alerts" v-if="alerts.length&&!monitoring"><button v-for="c in alerts" :key="c.id" @click="open(c)"><strong>{{c.company_name}}</strong> &middot; {{c.unread}} new announcement{{c.unread>1?'s':''}} <span>Open community &rarr;</span></button></div>
 <div class="comm-review-banner" v-if="monitoring">Read-only review: {{data?.viewed_user?.name}} &middot; You are viewing their conversations as Super Admin.</div>
 <p v-if="notice" class="comm-notice" role="status">{{notice}} <button @click="notice=''">Dismiss</button></p>
 <p v-if="error" class="comm-error" role="alert">{{error}} <button @click="error=''">Dismiss</button></p>
 <StatusPanel v-if="section==='Status'" :stories="visibleStories" :can-publish="!!data?.manager&&!monitoring" :can-delete="!!data?.admin&&!monitoring" :deleting-id="deletingStory" @remove="removeStory" :user-id="data?.user_id||null" :profile="data?.profile||null" :now="storyClock" :attachment="storyAttachment" @open="openStory" @publish="newModal('story')" @back="section='Chats'"/><div v-else class="comm-layout" :class="{'with-details':detailMode&&current}">
  <aside class="comm-sidebar">   <div class="comm-conversation-heading"><h2>{{section}}</h2><button v-if="!monitoring&&section==='Chats'" @click="newModal('chat')" aria-label="New conversation">+</button></div>
   <input class="comm-filter" v-model="filter" :placeholder="section==='Communities'?'Search communities':'Search or start a new chat'" aria-label="Search conversations">
   <div class="comm-conversations"><button v-for="c in conversations" :key="c.id" @click="open(c)" :class="{active:active===c.id}"><span class="comm-avatar" :class="c.kind"><img v-if="conversationAvatar(c)" :src="conversationAvatar(c)!" alt=""><template v-else>{{c.kind==='community'?'C':c.name.slice(0,1).toUpperCase()}}</template></span><span class="comm-conversation-copy"><strong>{{c.name}}</strong><small v-if="c.company_name">{{c.company_name}}</small><p>{{c.preview}}</p></span><span class="comm-conversation-status"><time v-if="c.last_message_at" :datetime="c.last_message_at" :title="timestamp(c.last_message_at)" :class="{unread:c.unread}">{{conversationTime(c.last_message_at)}}</time><b v-if="c.unread" class="comm-unread">{{c.unread}}</b></span></button><div class="comm-empty-small" v-if="!conversations.length">{{data?'No chats yet. Choose a contact from your community to get started.':'Loading your workspace...'}}</div></div>
   <div class="comm-team-list"><div class="comm-section-label">YOUR COMPANY</div><div v-for="c in data?.companies" :key="c.id"><span>{{c.name}}</span></div></div>
  </aside>
  <section class="comm-chat" v-if="current">
   <header class="comm-chat-heading"><button class="comm-back" @click="active=null;detailMode=''" aria-label="Back to conversations">&larr;</button><button class="comm-contact-trigger" aria-label="Open chat profile" @click="detailMode='info'"><span class="comm-avatar"><img v-if="conversationAvatar(current)" :src="conversationAvatar(current)!" alt=""><template v-else>{{current.kind==='community'?'C':current.name.slice(0,1)}}</template></span><span><h2>{{current.name}}</h2><p>{{current.kind==='direct'?'Click for contact info':current.company_name||current.members.map(m=>m.name).join(', ')}}</p></span></button><div class="comm-header-tools"><button aria-label="Search conversation" title="Search messages" @click="detailMode='search'"><svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg></button><button aria-label="Open chat details" title="Chat details" @click="detailMode=detailMode?'':'info'"><svg width="21" height="21" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><circle cx="12" cy="5" r="1.7"/><circle cx="12" cy="12" r="1.7"/><circle cx="12" cy="19" r="1.7"/></svg></button></div></header>
   <div class="comm-community-groups" v-if="current.kind==='community'"><span>Your groups</span><button v-for="g in data?.conversations.filter(c=>c.kind==='group'&&c.company_id===current?.company_id)" :key="g.id" @click="open(g)">{{g.name}}</button></div>
   <div class="comm-pinned-bar" v-if="pinned.length"><button v-for="m in pinned" :key="m.id" @click="jumpToMessage(m.id)"><span aria-hidden="true">&#128204;</span><span><strong>Pinned &middot; {{m.sender_name}}</strong><small>{{m.body||m.attachment_name}}</small></span></button></div>
   <div class="comm-messages" ref="list" aria-live="polite">
    <button class="comm-load-more" v-if="more" @click="loadMessages(false,true)">Load older messages</button>
    <div class="comm-empty-small" v-if="!messages.length">No messages{{search?' match your search':' yet'}}.</div>
    <template v-for="(m,index) in messages" :key="m.id"><div class="comm-day-divider" v-if="!index||messages[index-1].created_at.slice(0,10)!==m.created_at.slice(0,10)"><span>{{dayLabel(m.created_at)}}</span></div><article :id="'chat-message-'+m.id" class="comm-message" :class="{mine:mine(m),highlighted:highlight===m.id}"><span class="comm-message-avatar" :title="senderName(m)"><img v-if="avatar(m.sender_id)" :src="avatar(m.sender_id)!" :alt="senderName(m) + ' profile photo'"><template v-else>{{senderName(m).slice(0,1).toUpperCase()}}</template></span><div class="comm-message-meta"><strong>{{senderName(m)}}</strong></div><div class="comm-bubble"><span class="comm-forwarded-label" v-if="m.forwarded">&#8618; Forwarded</span><div v-if="m.reply_to" class="comm-reply-preview">Reply to {{messages.find(x=>x.id===m.reply_to)?.sender_name||'earlier message'}}: {{messages.find(x=>x.id===m.reply_to)?.body?.slice(0,100)||'#'+m.reply_to}}</div><p v-if="m.deleted_at" class="comm-deleted">This message was deleted.</p><p v-else>{{m.body}}</p><a v-if="m.attachment_url&&!m.deleted_at&&/\.(jpe?g|png|webp)$/i.test(m.attachment_name||'')" :href="download(m)+(viewUser?'&':'?')+'inline=1'" target="_blank" rel="noopener" class="comm-chat-image-link"><img :src="download(m)+(viewUser?'&':'?')+'inline=1'" :alt="m.attachment_name||'Shared image'" class="comm-chat-image" loading="lazy"></a><span v-if="m.attachment_url&&!m.deleted_at&&!/\.(jpe?g|png|webp)$/i.test(m.attachment_name||'')" class="comm-attachment">&#128206; {{m.attachment_name}}</span><small class="comm-bubble-time"><span v-if="m.edited_at&&!m.deleted_at">Edited &middot; </span>{{shortTime(m.created_at)}}</small></div><MessageActions v-if="!monitoring&&!m.deleted_at" :id="m.id" :mine="mine(m)" :can-reply="current.kind!=='community'||!!data?.admin" :can-react="!data?.admin" :can-pin="current.kind!=='community'||!!data?.admin" :pinned="!!m.pinned_at" :can-edit="mine(m)" :can-delete="!!data?.admin" :can-download="!!m.attachment_url" :contact="contactName(m)" @action="action(m,$event)" @reaction="react(m,$event)"/><div class="comm-reactions" v-if="!m.deleted_at"><button v-for="r in reactionGroups(m)" :key="r.emoji" :title="r.names.join(', ')" :class="{selected:r.mine}" :aria-label="'See reactions '+r.emoji+' ('+r.names.length+')'" @click="showReactions(m)">{{r.emoji}} {{r.names.length}}</button></div></article></template>
   </div>
   <div v-if="monitoring" class="comm-review-footer">Employee review is read-only. No messages are sent on their behalf.</div>
   <div v-else-if="current.kind==='community'&&!data?.admin" class="comm-review-footer">Only Super Admin can post here. You can react to announcements.</div>
   <form v-else class="comm-composer" :aria-busy="sending" @submit.prevent="send"><div v-if="reply" class="comm-composer-context">Replying to {{reply.sender_name}}: {{reply.body?.slice(0,80)}} <button type="button" @click="reply=null">&times;</button></div><div v-if="file" class="comm-composer-context">&#128206; {{file.name}} <button type="button" @click="file=null">&times;</button></div><div class="comm-composer-row"><input type="file" ref="fileInput" class="comm-file-input" @change="attached" accept=".jpg,.jpeg,.png,.webp,.pdf,.txt,.csv,.doc,.docx,.xls,.xlsx,.zip"><button type="button" @click="fileInput?.click()" aria-label="Attach file" title="Attach file (up to 10 MB)">+</button><EmojiPicker mode="composer" @select="insertEmoji"/><textarea ref="composerInput" v-model="draft" placeholder="Write a message..." aria-label="Message" rows="1" maxlength="10000" @keydown.enter.exact.prevent="send"></textarea><button class="comm-send" :disabled="sending||(!draft.trim()&&!file)" :aria-busy="sending"><span v-if="sending" class="comm-spinner" aria-hidden="true"></span><span>{{sending?'Sending...':'Send'}}</span><span v-if="!sending" aria-hidden="true">&rarr;</span></button></div><small>Enter to send &middot; Shift + Enter for a new line &middot; Files up to 10 MB</small></form>
  </section>
  <ChatDetails v-if="current&&detailMode" :conversation="current" :viewer="monitoring?Number(viewUser):data?.user_id||null" :mode="detailMode" :request="api" :avatar="avatar" :review-user="viewUser" @close="detailMode=''" @jump="jumpToMessage"/>
  <section class="comm-welcome" v-if="!current"><span class="comm-welcome-icon">&#9993;</span><h2>{{section==='Communities'?'Your communities':'Judibas Communication'}}</h2><p>{{section==='Communities'?'Choose your company community to read announcements and open your groups.':'Send messages, share files and stay connected with your team.'}}</p><button v-if="data&&!monitoring&&section==='Chats'" class="comm-primary" @click="newModal('chat')">Start a conversation &rarr;</button><p class="comm-welcome-note">Company communities, groups, and personal chats.</p></section>
 </div>
 <div v-if="modal||story" class="comm-modal-backdrop" @click.self="modal='';story=null"><section class="comm-modal" :class="{'comm-status-viewer':story&&!modal}" role="dialog" aria-modal="true" :aria-label="story?'Status update':modal"><button class="comm-modal-close" aria-label="Close" @click="modal='';story=null">&times;</button>
 <template v-if="modal==='reactions'"><h2>Message reactions</h2><nav class="comm-reaction-tabs" aria-label="Reaction filters"><button v-for="tab in reactionTabs" :key="tab" :class="{selected:reactionFilter===tab}" @click="reactionFilter=tab">{{tab}} <small>{{tab==='All'?reactionMessage?.reactions.length:reactionMessage?.reactions.filter(r=>r.emoji===tab).length}}</small></button></nav><div class="comm-reaction-people"><article v-for="r in reactionPeople" :key="r.user_id"><span class="comm-mini-avatar"><img v-if="avatar(r.user_id)" :src="avatar(r.user_id)!" alt=""><template v-else>{{r.name.slice(0,1)}}</template></span><div><strong>{{r.name}}<small v-if="r.user_id===data?.user_id"> (you)</small></strong><button v-if="r.user_id===data?.user_id&&!monitoring&&!data?.admin&&reactionMessage&&!reactionMessage.deleted_at" @click="react(reactionMessage,r.emoji)">Remove your reaction</button></div><span class="comm-person-emoji">{{r.emoji}}</span></article><p v-if="!reactionPeople.length" class="comm-muted">No reactions.</p></div></template>
 <CommunicationProfile v-else-if="modal==='profile'&&data?.profile" :profile="data.profile" :request="api" :can-publish-story="!!data.manager&&!monitoring" @publish-story="newModal('story')" @updated="profileUpdated" @close="modal=''"/>
 <form v-else-if="modal==='forward'" class="comm-forward-picker" @submit.prevent="forward"><h2>Forward message</h2><p class="comm-muted">Choose a conversation</p><blockquote>{{forwardMessage?.body||forwardMessage?.attachment_name}}</blockquote><input v-model="forwardFilter" aria-label="Search forwarding conversations" placeholder="Search chats"><div class="comm-forward-list"><label v-for="c in forwardChoices" :key="c.id"><input type="radio" required name="forward-target" :value="String(c.id)" v-model="forwardTarget"><span>{{c.name}}<small>{{c.kind==='community'?'Community':c.kind==='group'?'Group':'Personal chat'}}</small></span></label></div><p v-if="!forwardChoices.length" class="comm-muted">No conversations available.</p><button class="comm-primary" :disabled="saving||!forwardTarget">{{saving?'Forwarding...':'Forward'}}</button></form>
 <CommunicationManagement v-else-if="modal==='management'" :csrf="csrf" @changed="refresh"/>
 <template v-else-if="story"><div class="comm-status-lifetime" role="progressbar" aria-label="Status playback progress" :aria-valuenow="Math.round(storyPlayback)" :aria-valuemin="0" :aria-valuemax="100"><span :style="{width:storyPlayback+'%'}"></span></div><header class="comm-status-viewer-heading"><span class="comm-status-avatar"><img v-if="story.author_avatar" :src="story.author_avatar" alt=""><span v-else>{{(story.author_name||'Company Admin').slice(0,1)}}</span></span><div><strong>{{story.author_name||'Company Admin'}}</strong><time :datetime="story.created_at">{{storyPosted(story)}}</time></div></header><button class="comm-status-pause" :aria-label="storyPaused?'Resume status':'Pause status'" @click="toggleStatusPlayback">{{storyPaused?'▶':'Ⅱ'}}</button><div class="comm-story-timing"><span>{{storyRemaining(story)}}</span></div><button v-if="visibleStories.findIndex(s=>s.id===story?.id)>0" class="comm-status-previous" aria-label="Previous status" @click="nextStory(-1)"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m14 6-6 6 6 6"/></svg></button><button v-if="visibleStories.findIndex(s=>s.id===story?.id)<visibleStories.length-1" class="comm-status-next" aria-label="Next status" @click="nextStory(1)"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m10 6 6 6-6 6"/></svg></button><img v-if="story.attachment_url&&story.attachment_mime?.startsWith('image/')" class="comm-story-media" :key="story.id" :src="storyAttachment(story)" :alt="story.body||'Status photo'" @load="storyReady=true" @error="storyReady=true" @pointerdown="storyHeld=true"><video v-else-if="story.attachment_url&&story.attachment_mime?.startsWith('video/')" class="comm-story-media" :src="storyAttachment(story)" :key="story.id" ref="storyMedia" controls playsinline autoplay muted preload="metadata" @timeupdate="mediaStatusProgress" @ended="advanceStatus"></video><audio v-else-if="story.attachment_url&&story.attachment_mime?.startsWith('audio/')" class="comm-story-audio" :src="storyAttachment(story)" :key="story.id" ref="storyMedia" controls autoplay preload="metadata" @timeupdate="mediaStatusProgress" @ended="advanceStatus"></audio><p v-if="story.body" class="comm-story-body">{{story.body}}</p><a v-if="story.attachment_url&&!story.attachment_mime?.startsWith('image/')" class="comm-story-download" :href="storyAttachment(story,true)">&#128206; {{story.attachment_name}} &darr;</a><div class="comm-story-viewers" v-if="canViewStoryViewers(story)"><div class="comm-viewer-controls"><button aria-label="Show story viewers" @click="viewersOpen=!viewersOpen;if(viewersOpen)loadStoryViewers()">&#128065; Viewers ({{viewerTotal}})</button><button v-if="viewersOpen" :disabled="viewerBusy" @click="loadStoryViewers()">Refresh</button></div><div v-if="viewersOpen" class="comm-viewer-list"><article v-for="v in storyViewers" :key="v.id"><span class="comm-mini-avatar"><img v-if="v.avatar_url" :src="v.avatar_url" alt=""><template v-else>{{v.name.slice(0,1)}}</template></span><div><strong>{{v.name}}</strong><small>{{v.email}}</small><time>Viewed {{timestamp(v.last_viewed_at)}}</time></div></article><p v-if="!viewerBusy&&!storyViewers.length" class="comm-muted">No views yet.</p><button v-if="viewerNext" :disabled="viewerBusy" @click="loadStoryViewers(true)">Load more viewers</button></div><p v-if="viewerBusy" class="comm-muted" role="status">Loading viewers...</p></div><p v-if="viewerError" class="comm-error" role="alert">{{viewerError}}</p><button v-if="data?.admin&&!monitoring" class="comm-status-delete-viewer" :disabled="deletingStory!==null" @click="removeStory(story)"><span v-if="deletingStory===story.id" class="comm-spinner" aria-hidden="true"></span><svg v-else width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/></svg>{{deletingStory===story.id?'Deleting...':'Delete status'}}</button></template>
 <template v-else-if="modal==='audit'"><h2>Administrator review log</h2><p class="comm-muted">Latest 100 reviews and conversation/file views.</p><div class="comm-audit-list"><article v-for="a in auditRows" :key="a.id"><strong>{{a.action.replaceAll('_',' ')}}</strong><p>{{a.admin_email}} &middot; {{a.employee_name||'Company overview'}} <span v-if="a.conversation_id">&middot; Chat #{{a.conversation_id}}</span></p><small>{{timestamp(a.created_at)}}</small></article><p v-if="!auditRows.length">No reviews recorded yet.</p></div></template>
 <form v-else :aria-busy="saving" @submit.prevent="save"><h2>{{modal==='announcement'?'Send community announcement':modal==='story'?'Add status update':'New chat'}}</h2><p v-if="error" class="comm-error">{{error}}</p>
 <template v-if="modal==='chat'"><label>Conversation type<select v-model="modalKind" @change="selected=[]"><option v-if="!data?.admin" value="direct">Direct message</option><option value="group">Group chat</option></select></label><label v-if="modalKind==='group'">Company<select required v-model="modalTeam" @change="selected=[]"><option value="" disabled>Select a company</option><option v-for="t in data?.companies" :key="t.id" :value="t.id">{{t.name}}</option></select></label></template>
 <label v-if="modal==='chat'&&modalKind==='group'">Group name<input required v-model="modalName" maxlength="100"></label>
 <label v-if="modal==='story'||modal==='announcement'">{{modal==='story'?(storyFile?'Caption (optional)':'Status text'):'Announcement'}}<textarea v-model="modalBody" :required="modal==='story'&&!storyFile" :maxlength="modal==='story'?3000:10000" rows="6" placeholder="Share a company update"></textarea></label>
 <label v-if="modal==='story'" class="comm-story-upload">Attachment (optional)<input type="file" aria-label="Story attachment" ref="storyInput" @change="storyFile=($event.target as HTMLInputElement).files?.[0]||null" accept=".jpg,.jpeg,.png,.webp,.mp4,.webm,.mp3,.wav,.m4a,.pdf,.txt,.csv,.doc,.docx,.xls,.xlsx,.zip"><small>Photos, video, audio or documents &middot; Up to 20 MB. Add text, an attachment, or both.</small><button v-if="storyFile" type="button" @click="clearStoryAttachment">Remove attachment</button></label>
 <div v-if="modal==='chat'" class="comm-picker"><p>{{modalKind==='direct'&&modal==='chat'?'Choose one colleague':'Select members'}}</p><label v-for="p in candidates" :key="p.id"><input v-if="modal==='chat'&&modalKind==='direct'" type="radio" :checked="selected.includes(p.id)" @change="selected=[p.id]" name="recipient"><input v-else type="checkbox" v-model="selected" :value="p.id"><span>{{p.name}}<small>{{p.email}}</small></span></label><p v-if="!candidates.length">No employees have Communication access yet. Only people who share a community or group with you appear here.</p></div>

 <template v-if="modal==='announcement'"><fieldset class="comm-company-picker"><legend>Send to communities</legend><label v-for="c in data?.companies" :key="c.id"><input type="checkbox" v-model="announcementCompanies" :value="c.id">{{c.name}}</label></fieldset><label class="comm-announce-file">Attachment (optional)<input type="file" @change="announcementFile=($event.target as HTMLInputElement).files?.[0]||null" accept=".jpg,.jpeg,.png,.webp,.pdf,.txt,.csv,.doc,.docx,.xls,.xlsx,.zip"></label></template>
 <button class="comm-primary comm-loading-button" :disabled="saving" :aria-busy="saving"><span v-if="saving" class="comm-spinner" aria-hidden="true"></span><span>{{saving?(modal==='chat'?(modalKind==='group'?'Creating group...':'Creating chat...'):modal==='story'?'Publishing...':'Sending...'):modal==='story'?'Publish for 24 hours':modal==='announcement'?'Send announcement':'Create chat'}}</span></button><p v-if="saving" class="comm-request-status" role="status">{{modal==='chat'?'Setting up your conversation. Please wait.':'Please wait while your update is sent.'}}</p></form>
 </section></div>
</div>
</template>